int main(void) {
    int n, i, key, a[100], lo, hi, mid, pos = -1;
    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    if (scanf("%d", &key) != 1)
        return 0;
    lo = 0;
    hi = n - 1;
    while (lo <= hi) {
        mid = lo + (hi - lo) / 2;
        if (a[mid] == key) {
            pos = mid;
            break;
        } else if (a[mid] < key)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    printf("%d\n", pos);
    return 0;
}

