    top = 0;
    bottom = r - 1;
    left = 0;
    right = c - 1;
    total = r * c;
    count = 0;
    dir = 0;
    while (count < total) {
        if (dir == 0) {
            for (j = left; j <= right; j++) {
                printf("%d ", a[top][j]);
                count++;
            }
            top++;
        } else if (dir == 1) {
            for (i = top; i <= bottom; i++) {
                printf("%d ", a[i][right]);
                count++;
            }
            right--;
        } else if (dir == 2) {
            for (j = right; j >= left; j--) {
                printf("%d ", a[bottom][j]);
                count++;
            }
            bottom--;
        } else {
            for (i = bottom; i >= top; i--) {
                printf("%d ", a[i][left]);
                count++;
            }
            left++;
        }
        dir = (dir + 1) % 4;
    }
    printf("\n");
    return 0;
}

