#include <stdio.h>
void qs(int a[], int lo, int hi) {
    int i = lo - 1, j, t;
    if (lo >= hi)
        return;
    int pivot = a[hi];
    for (j = lo; j < hi; j++)
        if (a[j] <= pivot) {
            i++;
            t = a[i];
            a[i] = a[j];
            a[j] = t;
        }
    t = a[i + 1];
    a[i + 1] = a[hi];
    a[hi] = t;
    qs(a, lo, i);
    qs(a, i + 2, hi);
}
int main(void) {
