#include <stdio.h>
void sift(int a[], int i, int n) {
    int t = a[i], c = 2 * i + 1;
    while (c < n) {
        if (c + 1 < n && a[c] < a[c + 1])
            c++;
        if (a[c] <= t)
            break;
        a[i] = a[c];
        i = c;
        c = 2 * i + 1;
    }
    a[i] = t;
}
int main(void) {
    int n, i, a[1000], t;
    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = n / 2 - 1; i >= 0; i--)
        sift(a, i, n);
    for (i = n - 1; i > 0; i--) {
        t = a[0];
        a[0] = a[i];
        a[i] = t;
        sift(a, 0, i);
    }
    for (i = 0; i < n; i++)
        printf("%s%d", i ? " " : "", a[i]);
    printf("\n");
    return 0;
}

