#include <stdio.h>
int key[1000], idx[1000], tk[1000], ti[1000];
void merge(int lo, int mid, int hi) {
    int i = lo, j = mid + 1, t = 0;
    while (i <= mid && j <= hi) {
        if (key[i] <= key[j]) {
            tk[t] = key[i];
            ti[t] = idx[i];
            i++;
        } else {
            tk[t] = key[j];
            ti[t] = idx[j];
            j++;
        }
        t++;
    }
    while (i <= mid) {
        tk[t] = key[i];
        ti[t] = idx[i];
        i++;
        t++;
    }
    while (j <= hi) {
        tk[t] = key[j];
        ti[t] = idx[j];
        j++;
        t++;
    }
    for (i = 0; i < t; i++) {
        key[lo + i] = tk[i];
        idx[lo + i] = ti[i];
    }
}
