#include <stdio.h>
int main(void) {
    int n, i, j, s[100], e[100], cs, ce, t;
    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d %d", &s[i], &e[i]);
    for (i = 0; i < n; i++)
        for (j = i + 1; j < n; j++)
            if (s[j] < s[i] || (s[j] == s[i] && e[j] < e[i])) {
                t = s[i];
                s[i] = s[j];
                s[j] = t;
                t = e[i];
                e[i] = e[j];
                e[j] = t;
            }
    if (n == 0)
        return 0;
    cs = s[0];
    ce = e[0];
    for (i = 1; i < n; i++) {
        if (s[i] <= ce) {
            if (e[i] > ce)
                ce = e[i];
        } else {
            printf("%d %d\n", cs, ce);
            cs = s[i];
            ce = e[i];
        }
    }
    printf("%d %d\n", cs, ce);
    return 0;
}

