int a[200][200], pre[201][201];
int main(void) {
    int n, m, i, j, t, r1, c1, r2, c2;
    if (scanf("%d %d", &n, &m) != 2)
        return 0;
    for (i = 0; i <= n; i++)
        for (j = 0; j <= m; j++)
            pre[i][j] = 0;
    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            scanf("%d", &a[i][j]);
    for (i = 1; i <= n; i++)
        for (j = 1; j <= m; j++)
            pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + a[i - 1][j - 1];
    if (scanf("%d", &t) != 1)
        return 0;
    for (i = 0; i < t; i++) {
        scanf("%d %d %d %d", &r1, &c1, &r2, &c2);
        printf("%d\n", pre[r2 + 1][c2 + 1] - pre[r1][c2 + 1] - pre[r2 + 1][c1] + pre[r1][c1]);
    }
    return 0;
}

