#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int l, r;
} Itv;
int cmp(const void *a, const void *b) {
    Itv *x = (Itv *)a;
    Itv *y = (Itv *)b;
    return x->l - y->l;
}
int main() {
    int n;
    scanf("%d", &n);
    Itv it[1000];
    for (int i = 0; i < n; i++)
        scanf("%d %d", &it[i].l, &it[i].r);
    qsort(it, n, sizeof(Itv), cmp);
    if (n == 0) {
        printf("0");
        return 0;
    }
    int cnt = 1;
    int cl = it[0].l, cr = it[0].r;
    for (int i = 1; i < n; i++) {
        if (it[i].l <= cr) {
            if (it[i].r > cr)
                cr = it[i].r;
        } else {
            cnt++;
            cl = it[i].l;
            cr = it[i].r;
        }
    }
    printf("%d", cnt);
    return 0;
}

