int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    int alive[1000];
    for (int i = 0; i < n; i++)
        alive[i] = 1;
    int remain = n, pos = 0, step = 0;
    while (remain > 1) {
        if (alive[pos])
            step++;
        if (step == m) {
            alive[pos] = 0;
            remain--;
            step = 0;
        }
        pos = (pos + 1) % n;
    }
    for (int i = 0; i < n; i++)
        if (alive[i])
            printf("%d", i + 1);
    return 0;
}

