#include <stdio.h>

int main(void) {
    int a[9][9];
    int n, i, j, num;
    int top, bottom, left, right;

    if (scanf("%d", &n) != 1)
        return 1;
    if (n < 1 || n > 9)
        return 1;

    /* 一圈一圈顺时针填数：上边 -> 右边 -> 下边 -> 左边 */
    top = 0;
    bottom = n - 1;
    left = 0;
    right = n - 1;
    num = 1;
    while (top <= bottom && left <= right) {
        for (j = left; j <= right; j++)
            a[top][j] = num++;
        top = top + 1;
        for (i = top; i <= bottom; i++)
            a[i][right] = num++;
        right = right - 1;
        if (top <= bottom) {
            for (j = right; j >= left; j--)
                a[bottom][j] = num++;
            bottom = bottom - 1;
        }
        if (left <= right) {
            for (i = bottom; i >= top; i--)
                a[i][left] = num++;
            left = left + 1;
        }
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            printf("%4d", a[i][j]);
        printf("\n");
    }

    return 0;
}

