#include <stdio.h>

void bubbleSort(int a[], int n) {
    int i, j, t, flag;

    for (i = 0; i < n - 1; i++) {
        flag = 0;
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                flag = 1;
            }
        if (flag == 0)
            break;
