#include <stdio.h>

int binSearch(int a[], int n, int x) {
    int low = 0, high = n - 1, mid;

    while (low <= high) {
        mid = (low + high) / 2;
        if (a[mid] == x)
            return mid;
        if (a[mid] < x)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1;
}

int main(void) {
    int a[100], n, i, x;

    if (scanf("%d", &n) != 1 || n < 1 || n > 100)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    if (scanf("%d", &x) != 1)
        return 1;
    printf("%d\n", binSearch(a, n, x));
    return 0;
}

